<div class="page-heading"><div><p class="eyebrow">Alunos</p><h1>Nova matrícula</h1><p class="meta">Vincule um aluno cadastrado a um curso existente no Moodle.</p></div><a class="button-secondary" href="<?= $escape($basePath) ?>/students/enrollments">Cancelar</a></div>
<?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/students/enrollments"><?= $csrfField ?><div class="form-grid"><div class="form-field"><label>Unidade <span class="required">*</span></label><select name="unit_id" required><option value="">Selecione</option><?php foreach($units as$unit):?><option value="<?= (int)$unit['id'] ?>"><?= $escape($unit['name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label>Aluno <span class="required">*</span></label><select name="finance_customer_id" required><option value="">Selecione</option><?php foreach($students as$student):?><option value="<?= (int)$student['id'] ?>"><?= $escape($student['name'].' · '.$student['unit_name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label>Curso no Moodle <span class="required">*</span></label><select name="moodle_course_id" required><option value="">Selecione</option><?php foreach($courses as$course):?><option value="<?= (int)$course['id'] ?>"><?= $escape($course['fullname'].' · '.$course['shortname']) ?></option><?php endforeach;?></select></div><div class="form-field"><label>Curso e preço para cobrança</label><select name="finance_product_id"><option value="">Definir depois</option><?php foreach($products as$product):?><option value="<?= (int)$product['id'] ?>"><?= $escape($product['name'].' · R$ '.number_format((float)$product['value'],2,',','.')) ?></option><?php endforeach;?></select></div></div><div class="alert alert-warning"><strong>Fluxo seguro:</strong> esta etapa prepara a matrícula. A cobrança e a liberação no Moodle serão confirmadas separadamente.</div><button class="button-primary" type="submit"><i class="fa-solid fa-graduation-cap"></i> Criar matrícula</button></form></div></section>
